using System;using System.Diagnostics;using System.Runtime.InteropServices;using System.Threading;using System.Windows.Automation;
public sealed class SaveNativeDialog {
[DllImport("user32.dll",CharSet=CharSet.Unicode)]static extern IntPtr FindWindow(string cls,string title);
[DllImport("user32.dll")]static extern uint GetWindowThreadProcessId(IntPtr h,out uint pid);
Thread worker;public bool Saved;public string Error;
public SaveNativeDialog(string path){worker=new Thread(delegate(){try{Stopwatch clock=Stopwatch.StartNew();while(clock.ElapsedMilliseconds<10000){IntPtr h=FindWindow("#32770","Сохранить режим");uint pid=0;if(h!=IntPtr.Zero)GetWindowThreadProcessId(h,out pid);if(h!=IntPtr.Zero&&pid==(uint)Process.GetCurrentProcess().Id){AutomationElement dialog=AutomationElement.FromHandle(h);AutomationElementCollection edits=dialog.FindAll(TreeScope.Descendants,new PropertyCondition(AutomationElement.ControlTypeProperty,ControlType.Edit));AutomationElement filename=null;foreach(AutomationElement edit in edits){object pattern;if(edit.TryGetCurrentPattern(ValuePattern.Pattern,out pattern)&&((ValuePattern)pattern).Current.Value=="Режим.exe"){filename=edit;break;}}if(filename==null){Thread.Sleep(150);continue;}((ValuePattern)filename.GetCurrentPattern(ValuePattern.Pattern)).SetValue(path);AutomationElement button=dialog.FindFirst(TreeScope.Descendants,new AndCondition(new PropertyCondition(AutomationElement.ControlTypeProperty,ControlType.Button),new PropertyCondition(AutomationElement.AutomationIdProperty,"1")));if(button==null)throw new Exception("Save button not found");((InvokePattern)button.GetCurrentPattern(InvokePattern.Pattern)).Invoke();Saved=true;return;}Thread.Sleep(100);}throw new Exception("Save dialog timed out");}catch(Exception ex){Error=ex.ToString();}});worker.SetApartmentState(ApartmentState.MTA);worker.IsBackground=true;worker.Start();}
public bool Wait(){return worker.Join(12000)&&Saved;}
}
